mapper.insert:
INSERT INTO cps_inventory_alert_event (
    item_id, status, first_triggered_at, last_eval_at, last_eval_qty,
    threshold_snapshot, closed_at, closed_by, close_reason
) VALUES (
    #{itemId}, #{status}, #{firstTriggeredAt}, #{lastEvalAt}, #{lastEvalQty},
    #{thresholdSnapshot}, #{closedAt}, #{closedBy}, #{closeReason}
)

mapper.select:
SELECT e.id, e.item_id, e.status, e.first_triggered_at, e.last_eval_at, e.last_eval_qty, e.threshold_snapshot, e.closed_at, e.closed_by, e.close_reason, e.created_at, e.updated_at, i.item_code, i.item_name, i.unit, i.stock_qty AS current_stock_qty, i.alert_threshold AS current_alert_threshold FROM cps_inventory_alert_event e JOIN cps_inventory_item i ON i.id = e.item_id WHERE 1 = 1
AND e.status = #{status}
AND e.item_id = #{itemId}
ORDER BY e.last_eval_at DESC, e.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM cps_inventory_alert_event e
WHERE 1 = 1

  AND e.status = #{status}


  AND e.item_id = #{itemId}
